# Code generated by Claude
"""Tables for the checker-start report from the result.json files of experiments/checker_start_compare.py:  python experiments/checker_start_report.py data/checker_start/<TAG>"""
import json
import sys
from collections import Counter, defaultdict
from pathlib import Path

root = Path(sys.argv[1])
R = {p.parent.name: json.loads(p.read_text()) for p in sorted(root.glob("*/result.json"))}


def key(e):
    return (tuple(e["stance"]), e["theta_deg"], e["path"], tuple(e["p"]))


for layout in ("normal", "moved"):
    a, b = R.get(f"{layout}_today"), R.get(f"{layout}_neighbourhood")
    if not a or not b:
        continue
    print(f"\n## {layout} layout\n")
    for nm, r in (("today", a), ("neighbourhood", b)):
        print(f"- {nm}: selection ok {r['ok']}; chosen spot {r['chosen_stance']}; place angle {r['place_theta_deg']}; selection time {r['selection_seconds']:.1f} s; {len(r['calls'])} full-check calls "
              f"({sum(1 for c in r['calls'] if c['ok'])} passed); stops logged {sum(len(c['start_log']) for c in r['calls'])}; full check seconds {sum(c['seconds'] for c in r['calls']):.1f}")
    # today's random use
    logs = [e for c in a["calls"] for e in c["start_log"]]
    ok_stops = [e for e in logs if e["ok"]]
    resc = [e for e in logs if e["rescue"]]
    forced = [e for e in logs if e["forced_random"]]
    print(f"\nToday's checker: {len(logs)} stops solved ({len(ok_stops)} passed). Passed from a warm start: {sum(1 for e in ok_stops if e['source'] in ('nominal', 'previous point'))}; "
          f"FORCED random (no start to try: the first stop of a path at a stance): {len(forced)}; RESCUE (warm starts tried and failed, a random start passed): {len(resc)}; failed: {len(logs) - len(ok_stops)}.")
    by = Counter((e["path"], e["pose"]) for e in resc)
    print("Rescues by path:", dict(by) if by else "none")
    by2 = Counter((e["path"]) for e in forced)
    print("Forced random by path:", dict(by2) if by2 else "none")
    chosen = a["chosen_stance"]
    if chosen:
        ch = None
        for c in a["calls"]:
            if c["ok"]:
                ch = c
        nominal = ch["stance"] if ch else None
        mine = [e for e in ch["start_log"]] if ch else []
        resc_ch = [e for e in mine if e["rescue"]]
        forced_ch = [e for e in mine if e["forced_random"]]
        print(f"On the chosen spot's check ({nominal}): {len(mine)} stops, rescues {len(resc_ch)}, forced random {len(forced_ch)}.")
        for e in resc_ch[:20]:
            print(f"   rescue: stance {e['stance']} path {e['path']} pose {e['pose']} p {e['p']} theta {e['theta_deg']}")
        # nominal stance only
        nom = [e for e in mine if abs(e["stance"][0] - nominal[0]) < 1e-3 and abs(e["stance"][1] - nominal[1]) < 1e-3 and abs(e["stance"][2] - nominal[2]) < 1e-3 and abs(e["stance"][3] - nominal[3]) < 1e-3]
        place_theta = a["place_theta_deg"]
        at_theta = [e for e in nom if e["theta_deg"] in (None, place_theta)]
        print(f"  at the nominal stance and the chosen angle: {len(at_theta)} stops, rescues {sum(1 for e in at_theta if e['rescue'])}, forced random {sum(1 for e in at_theta if e['forced_random'])}")
    # differences
    da, db = {}, {}
    for c in a["calls"]:
        for e in c["start_log"]:
            da[(tuple(c["stance"]),) + key(e)] = e
    for c in b["calls"]:
        for e in c["start_log"]:
            db[(tuple(c["stance"]),) + key(e)] = e
    both = set(da) & set(db)
    diff = [(k, da[k], db[k]) for k in both if da[k]["ok"] != db[k]["ok"]]
    only_a = len(set(da) - set(db))
    only_b = len(set(db) - set(da))
    print(f"\nStops solved in both ways: {len(both)} (only today {only_a}, only neighbourhood {only_b}: a stance that failed earlier in one way is not solved further). Pass/fail differs at {len(diff)}.")
    cnt = Counter((x[1]["path"], x[1]["pose"], "today pass, neighbourhood FAIL" if x[1]["ok"] else "today FAIL, neighbourhood pass") for x in diff)
    for k, v in cnt.most_common(12):
        print("  ", k, v)
    resc_diag = [e for c in b["calls"] for e in c["start_log"] if e.get("rescuable") is True]
    print(f"Neighbourhood mode: stops that FAILED but a random start could reach: {len(resc_diag)} ('failed, but another arm shape could reach it'); failed with no rescue possible: {sum(1 for c in b['calls'] for e in c['start_log'] if (not e['ok']) and e.get('rescuable') is False)}")
    # spots: verdict per call
    sa = {tuple(round(v, 3) for v in c["stance"]): (c["ok"], c["failed"]) for c in a["calls"]}
    sb = {tuple(round(v, 3) for v in c["stance"]): (c["ok"], c["failed"]) for c in b["calls"]}
    print("\nSpot verdicts (stance x y heading q) today / neighbourhood:")
    for k in sorted(set(sa) | set(sb)):
        print(f"  {k}: {sa.get(k, '-')} / {sb.get(k, '-')}")
    # place windows
    for nm, r in (("today", a), ("neighbourhood", b)):
        for c in r["calls"]:
            if c.get("place"):
                pl = c["place"]
                print(f"  place window {nm} at {[round(v, 3) for v in c['stance']]}: theta {pl.get('theta_deg')} window {pl.get('window_deg')} width {pl.get('width_deg')} passing turns {len(pl.get('passing_deg', []))}")
